const $=id=>document.getElementById(id), dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=dateKey(new Date());let selected=today,view=new Date(new Date().getFullYear(),new Date().getMonth(),1),exercises=[],filter='All moves',query='',preview=null,records={},storageOK=true,entryMode='plan',period='day';
try{const saved=JSON.parse(localStorage.getItem('gym-stone-v1')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const [day,rows]of Object.entries(saved))if(/^\d{4}-\d{2}-\d{2}$/.test(day)&&Array.isArray(rows))records[day]=rows.filter(r=>r&&typeof r.id==='string'&&typeof r.done==='boolean').filter((r,i,a)=>a.findIndex(x=>x.id===r.id)===i);}catch{storageOK=false}
function notify(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').classList.remove('visible'),2600)}
async function save(){render();document.querySelector('.save-label').textContent='○ Saving…';try{await GymScreenshotStore.putRecords(structuredClone(records));storageOK=true;try{localStorage.setItem('gym-stone-v1',JSON.stringify(records))}catch{}}catch{storageOK=false;notify('Changes could not be saved. Keep this tab open and check browser storage.')}document.querySelector('.save-label').textContent=storageOK?'● Saved on this device':'○ Unsaved changes';return storageOK}
function recordExercise(r){return exercises.find(e=>e.id===r.id)||(r.name?{id:r.id,name:r.name,group:r.group||'Activity'}:null)}

function rows(){return records[selected]||[]}
function add(id){if(entryMode==='done'&&selected>today){notify('Future days are for planning. Select today or a past day to log a workout.');return}if(!exercises.some(e=>e.id===id))throw Error('Unknown exercise');if(rows().some(r=>r.id===id))return;records[selected]=[...rows(),{id,done:entryMode==='done',minutes:0,time:''}];save();notify(entryMode==='done'?'+25 XP · Workout logged. Add its duration above.':'Added to your daily quest');renderPreview()}
function toggle(id){const r=rows().find(x=>x.id===id);if(!r)return;if(!r.done&&selected>today){notify('You can complete workouts on today or a past day.');return}r.done=!r.done;save();if(r.done)notify('+25 XP · One move stronger!')}
function selectDay(key){selected=key;const d=new Date(key+'T12:00:00');view=new Date(d.getFullYear(),d.getMonth(),1);render()}
function render(){renderCalendar();renderDay();renderStats();renderExercises();renderHours()}
function renderCalendar(){ $('month-label').textContent=view.toLocaleDateString(undefined,{month:'long',year:'numeric'});const start=new Date(view);start.setDate(1-start.getDay());const days=Math.ceil((view.getDay()+new Date(view.getFullYear(),view.getMonth()+1,0).getDate())/7)*7;$('calendar-grid').replaceChildren();for(let i=0;i<days;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=dateKey(d),rs=records[key]||[],done=rs.filter(r=>r.done).length,b=document.createElement('button');b.className='date-cell'+(d.getMonth()!==view.getMonth()?' outside':'')+(key===selected?' selected':'')+(key===today?' today':'')+(done?' trained':'');b.setAttribute('aria-pressed',String(key===selected));b.setAttribute('aria-label',d.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'})+`, ${rs.length} planned, ${done} completed`);if(key===today)b.setAttribute('aria-current','date');b.innerHTML=`<span class="day-number">${d.getDate()}</span>${done?'<span class="date-check">✓</span>':''}<span class="calendar-duration">${dayMinutes(key)?formatHours(dayMinutes(key)):''}</span><span class="day-dots">${rs.length>done?'<i class="dot planned"></i>':''}${done?'<i class="dot completed"></i>':''}</span>`;b.onclick=()=>selectDay(key);$('calendar-grid').append(b)}}
function renderDay(){const list=rows(),done=list.filter(r=>r.done).length;$('day-relative').textContent=selected===today?"TODAY'S QUEST":'DAILY QUEST';$('day-title').textContent=new Date(selected+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});$('day-count').textContent=`${list.length} move${list.length===1?'':'s'}`;$('day-progress-text').textContent=list.length?`${done} of ${list.length} completed`:'Your next win starts here';$('day-xp').textContent=`+${done*25} XP`;$('day-bar').style.width=list.length?`${done/list.length*100}%`:'0%';$('daily-list').replaceChildren();if(!list.length){$('daily-list').innerHTML='<div class="empty-day"><span class="empty-icon">✧</span><h3>A fresh start awaits</h3><p>Add moves from the library below to build this day’s workout.</p></div>';return}for(const r of list){const e=recordExercise(r);if(!e)continue;const el=document.createElement('div');el.className='daily-row';const check=document.createElement('button');check.className='check'+(r.done?' done':'');check.textContent=r.done?'✓':'';check.setAttribute('aria-label',(r.done?'Mark incomplete: ':'Complete: ')+e.name);check.setAttribute('aria-pressed',String(r.done));check.onclick=()=>toggle(r.id);const info=document.createElement('div');info.className='row-info';const name=document.createElement('b');name.textContent=e.name;name.className=r.done?'done-text':'';const group=document.createElement('span');group.textContent=e.group+' · 25 XP';info.append(name,group);if(r.done){const fields=document.createElement('div');fields.className='duration-fields';const label=document.createElement('label');label.textContent='Minutes ';const input=document.createElement('input');input.type='number';input.min='0';input.max='1440';input.step='0.01';input.value=r.minutes||0;input.setAttribute('aria-label','Minutes spent on '+e.name);input.onchange=()=>{r.minutes=Math.max(0,Math.min(1440,Math.round((Number(input.value)||0)*100)/100));save()};label.append(input);const timeLabel=document.createElement('label');timeLabel.textContent='Start ';const time=document.createElement('input');time.type='time';time.value=r.time||'';time.setAttribute('aria-label','Optional start time for '+e.name);time.onchange=()=>{r.time=time.value;save()};timeLabel.append(time);fields.append(label,timeLabel);info.append(fields)}if(r.source){const meta=document.createElement('span');meta.className='activity-meta';meta.textContent=r.source+(r.distance?' · '+r.distance.value+' '+r.distance.unit:'')+(r.calories!=null?' · '+r.calories+' kcal':'');info.append(meta)}if(r.screenshotIds?.length){const photo=document.createElement('button');photo.className='attachment-link';photo.textContent='▧ View screenshot'+(r.screenshotIds.length>1?' ('+r.screenshotIds.length+')':'');photo.setAttribute('aria-label','View attached screenshot for '+e.name);photo.onclick=()=>GymScreenshotImport.openView(r.screenshotIds[0]);info.append(photo)}const remove=document.createElement('button');remove.className='remove';remove.textContent='×';remove.setAttribute('aria-label','Remove '+e.name);remove.onclick=()=>{records[selected]=rows().filter(x=>x.id!==r.id);save();renderPreview();notify(r.screenshotIds?.length?'Workout removed · Screenshot kept in saved screenshots':'Move removed')};el.append(check,info,remove);$('daily-list').append(el)}}
function renderStats(){const total=Object.values(records).flat().filter(r=>r.done).length,xp=total*25,level=Math.floor(xp/200)+1;$('level').innerHTML=`${String(level).padStart(2,'0')} <small>${level<3?'Rookie':level<6?'Challenger':level<10?'Warrior':'Legend'}</small>`;$('xp-text').textContent=`${xp%200} / 200 XP to next level`;$('xp-bar').style.width=`${xp%200/2}%`;const month=dateKey(view).slice(0,7);$('month-workouts').innerHTML=`${Object.entries(records).filter(([d])=>d.startsWith(month)).flatMap(([,rs])=>rs).filter(r=>r.done).length} <small>moves completed</small>`;let streak=0,cursor=new Date(today+'T12:00:00');if(!(records[dateKey(cursor)]||[]).some(r=>r.done))cursor.setDate(cursor.getDate()-1);while((records[dateKey(cursor)]||[]).some(r=>r.done)){streak++;cursor.setDate(cursor.getDate()-1)}$('streak').innerHTML=`${streak} <small>${streak===1?'day':'days'}</small>`}
function renderExercises(){const found=exercises.filter(e=>(filter==='All moves'||e.group===filter||e.groups?.includes(filter))&&e.name.toLowerCase().includes(query));$('library-count').textContent=exercises.length+' moves';$('results-label').textContent=`${found.length} exercises · Adding to ${new Date(selected+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'})}`;const grid=$('exercise-grid'),scroll=grid.scrollTop;grid.replaceChildren();if(!found.length){grid.innerHTML='<p>No exercises match. Try another name or muscle group.</p>';return}for(const e of found){const exists=rows().some(r=>r.id===e.id),card=document.createElement('article');card.className='exercise-card';const visual=document.createElement('button');visual.className='exercise-visual';visual.setAttribute('aria-label','Preview '+e.name);const img=document.createElement('img');img.src=e.image;img.alt=e.name+' exercise animation';img.loading='lazy';img.decoding='async';const badge=document.createElement('span');badge.className='preview-label';badge.textContent=e.style==='Illustrated guide'?'Illustrated loop':'Anime GIF';visual.append(img,badge);visual.onclick=()=>openPreview(e);const body=document.createElement('div');body.className='exercise-body';const tag=document.createElement('span');tag.className='group-label';tag.textContent=e.group;const title=document.createElement('h3');title.textContent=e.name;const button=document.createElement('button');button.className='add-exercise'+(exists?' added':'');button.textContent=exists?'✓ In your quest':(entryMode==='done'?'+ Log completed':'+ Plan for day');button.disabled=exists;button.setAttribute('aria-label',(exists?'Already added: ':'Add to selected day: ')+e.name);button.onclick=()=>add(e.id);body.append(tag,title,button);card.append(visual,body);grid.append(card)}grid.scrollTop=scroll}
function openPreview(e){preview=e;$('preview-image').src=e.image;$('preview-image').alt=e.name+' exercise animation';$('preview-group').textContent=e.group;$('preview-name').textContent=e.name;renderPreview();$('exercise-dialog').showModal()}
function renderPreview(){if(!preview)return;const exists=rows().some(r=>r.id===preview.id);$('preview-add').textContent=exists?'✓ In your quest':(entryMode==='done'?'+ Log completed · ':'+ Plan for ')+new Date(selected+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'});$('preview-add').disabled=exists}
$('prev').onclick=()=>{view.setMonth(view.getMonth()-1);renderCalendar();renderStats()};$('next').onclick=()=>{view.setMonth(view.getMonth()+1);renderCalendar();renderStats()};$('today').onclick=()=>selectDay(today);$('search').oninput=e=>{query=e.target.value.trim().toLowerCase();$('exercise-grid').scrollTop=0;renderExercises()};document.querySelector('.dialog-close').onclick=()=>$('exercise-dialog').close();$('exercise-dialog').onclick=e=>{if(e.target===$('exercise-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('preview-add').onclick=()=>add(preview.id);
async function init(){try{const stored=await GymScreenshotStore.getRecords();if(stored&&typeof stored==='object'&&!Array.isArray(stored)){records=stored}else await GymScreenshotStore.putRecords(structuredClone(records));storageOK=true}catch{storageOK=false}render();try{const response=await fetch('exercises.json');if(!response.ok)throw Error('Could not load exercise library');exercises=await response.json();const allowed=new Set(exercises.map(e=>e.id));for(const day in records)records[day]=records[day].filter(r=>allowed.has(r.id)||(typeof r.name==='string'&&r.name.trim()));for(const group of ['All moves',...new Set(exercises.flatMap(e=>e.groups||[e.group]))]){const b=document.createElement('button');b.textContent=group;b.className=group===filter?'active':'';b.setAttribute('aria-pressed',String(group===filter));b.onclick=()=>{filter=group;for(const button of $('filters').children){button.classList.toggle('active',button===b);button.setAttribute('aria-pressed',String(button===b))}$('exercise-grid').scrollTop=0;renderExercises()};$('filters').append(b)}render();if(!storageOK){document.querySelector('.save-label').textContent='○ Session only';notify('Browser storage is unavailable. Screenshot imports cannot be saved.')}registerTools();connectScreenshotImport()}catch{$('exercise-grid').innerHTML='<p>The exercise library could not load. <button class="primary" onclick="location.reload()">Retry</button></p>'}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(const tool of [{name:'read_workout_calendar',description:'Read workout plans and completion status saved on this device.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({selected,records,exercises:exercises.map(({id,name,group})=>({id,name,group}))})},{name:'add_workouts_to_day',description:'Add exercises to a calendar day without marking them complete.',inputSchema:{type:'object',properties:{date:{type:'string'},exerciseIds:{type:'array',items:{type:'string'}}},required:['date','exerciseIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||!Array.isArray(input.exerciseIds)||input.exerciseIds.some(id=>!exercises.some(e=>e.id===id)))throw Error('Supply a valid date and known exercise IDs');const d=new Date(input.date+'T12:00:00');if(isNaN(d)||dateKey(d)!==input.date)throw Error('Invalid calendar date');selectDay(input.date);const existing=new Set(rows().map(r=>r.id));records[selected]=[...rows(),...Array.from(new Set(input.exerciseIds)).filter(id=>!existing.has(id)).map(id=>({id,done:false}))];save();return{date:selected,workouts:rows()}}}])try{Promise.resolve(context.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}}

function minutes(r){return r.done?Math.max(0,Math.min(1440,Number(r.minutes)||0)):0}
function dayMinutes(key){return(records[key]||[]).reduce((n,r)=>n+minutes(r),0)}
function formatHours(m){return (m/60).toLocaleString(undefined,{maximumFractionDigits:2})+' h'}
function rangeDates(start,count){return Array.from({length:count},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return dateKey(d)})}
function renderHours(){const day=new Date(selected+'T12:00:00'),week=new Date(day);week.setDate(week.getDate()-week.getDay());const weekKeys=rangeDates(week,7),monthStart=new Date(day.getFullYear(),day.getMonth(),1),monthKeys=rangeDates(monthStart,new Date(day.getFullYear(),day.getMonth()+1,0).getDate());$('day-hours').textContent=formatHours(dayMinutes(selected));$('week-hours').textContent=formatHours(weekKeys.reduce((s,k)=>s+dayMinutes(k),0));$('month-hours').textContent=formatHours(monthKeys.reduce((s,k)=>s+dayMinutes(k),0));$('total-days').textContent=Object.values(records).filter(rs=>rs.some(r=>r.done)).length;
let buckets=[],label='';if(period==='day'){buckets=Array.from({length:24},(_,i)=>({label:String(i).padStart(2,'0'),value:0}));let untimed=0;for(const r of rows()){if(!r.done)continue;const m=minutes(r);if(/^([01]\d|2[0-3]):[0-5]\d$/.test(r.time||'')){buckets[Number(r.time.slice(0,2))].value+=m}else untimed+=m}if(untimed)buckets.push({label:'No time',value:untimed});label='Selected day · hours grouped by workout start time'}else{const keys=period==='week'?weekKeys:monthKeys;buckets=keys.map(key=>({label:period==='week'?new Date(key+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'}):String(Number(key.slice(-2))),value:dayMinutes(key)}));label=period==='week'?'Week of '+week.toLocaleDateString(undefined,{month:'short',day:'numeric'})+' · hours per day':day.toLocaleDateString(undefined,{month:'long',year:'numeric'})+' · hours per day'}
$('chart-label').textContent=label;$('chart-total').textContent=formatHours(buckets.reduce((s,b)=>s+b.value,0));const chart=$('hours-chart');chart.replaceChildren();const max=Math.max(60,...buckets.map(b=>b.value));for(const b of buckets){const col=document.createElement('div');col.className='hour-column';col.setAttribute('aria-label',b.label+': '+formatHours(b.value));col.title=b.label+': '+formatHours(b.value);const val=document.createElement('span');val.className='hour-value';val.textContent=b.value?formatHours(b.value):'';const track=document.createElement('div');track.className='hour-track';const bar=document.createElement('i');bar.style.height=(b.value/max*100)+'%';track.append(bar);const name=document.createElement('span');name.className='hour-label';name.textContent=b.label;col.append(val,track,name);chart.append(col)}const missing=rows().filter(r=>r.done&&!minutes(r)).length;$('time-note').textContent=missing?`${missing} completed exercise${missing===1?' needs':'s need'} a duration. Enter minutes in the daily quest above.`:'Totals use the minutes you enter for completed exercises. Start time is optional.'}
for(const button of $('period-tabs').children)button.onclick=()=>{period=button.dataset.period;for(const b of $('period-tabs').children){b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))}renderHours()};
function setMode(mode){entryMode=mode;for(const [id,value]of [['mode-plan','plan'],['mode-done','done']]){const b=$(id);b.classList.toggle('active',mode===value);b.setAttribute('aria-pressed',String(mode===value))}renderExercises();renderPreview()}
$('mode-plan').onclick=()=>setMode('plan');$('mode-done').onclick=()=>setMode('done');
function connectScreenshotImport(){GymScreenshotImport.connect({getDay:()=>selected,today,dateKey,getRecords:()=>records,nameOf:r=>recordExercise(r)?.name||r.name||'Workout',setRecords:next=>{records=next;storageOK=true;try{localStorage.setItem('gym-stone-v1',JSON.stringify(records))}catch{}document.querySelector('.save-label').textContent='● Saved on this device'},selectDay,render,notify,setImportBusy:busy=>{document.querySelector('.save-label').textContent=busy?'○ Saving…':storageOK?'● Saved on this device':'○ Unsaved changes'}});$('screenshot-storage-label').textContent='Screenshots and workout records stay in this browser on this device. Review details before saving.'}
init();



